-- IAM owns this schema. Common migrations install auriga_enable_tenant_rls first.
CREATE TABLE iam."account" (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, lookup_key text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, UNIQUE (tenant_id, lookup_key), UNIQUE (tenant_id, id));
